"use client"

import { useState } from "react"
import { MainLayout } from "@/components/main-layout"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { Plus, Search, Package, Trash2, Edit } from "lucide-react"
import { useDataStore } from "@/lib/data-store"
import { formatUSD } from "@/lib/money"

export default function ProductsPage() {
  const [searchQuery, setSearchQuery] = useState("")
  const [categoryFilter, setCategoryFilter] = useState("all")
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [formData, setFormData] = useState({
    name: "",
    category: "Interior Paint",
    price: 0,
    unit: "gallon",
    stock: 0,
    description: "",
  })

  const { products, addProduct, deleteProduct } = useDataStore()
  const { updateProduct } = useDataStore()

  const [editingProduct, setEditingProduct] = useState<any | null>(null)
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false)
  const [editFormData, setEditFormData] = useState({
    name: "",
    category: "",
    price: 0,
    unit: "",
    stock: 0,
    description: "",
  })

  const filteredProducts = products.filter((product) => {
    const matchesSearch =
      product.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      product.category.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesCategory = categoryFilter === "all" || product.category === categoryFilter
    return matchesSearch && matchesCategory
  })

  const categories = Array.from(new Set(products.map((p) => p.category)))

  const handleSubmit = () => {
    if (!formData.name || !formData.category || formData.price <= 0) {
      alert("Please fill all required fields")
      return
    }

    addProduct({
      id: Date.now().toString(),
      ...formData,
    })

    setFormData({
      name: "",
      category: "Interior Paint",
      price: 0,
      unit: "gallon",
      stock: 0,
      description: "",
    })
    setIsDialogOpen(false)
  }

  const totalValue = products.reduce((sum, p) => sum + p.price * p.stock, 0)
  const lowStockCount = products.filter((p) => p.stock < 50).length

  return (
    <MainLayout>
      <div className="p-4 sm:p-6">
        <div className="mx-auto max-w-7xl space-y-6">
          <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h2 className="text-2xl font-bold tracking-tight sm:text-3xl">Products</h2>
              <p className="text-sm text-muted-foreground sm:text-base">Manage your product catalog and inventory</p>
            </div>
            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
              <DialogTrigger asChild>
                <Button variant="brand">
                  <Plus className="mr-2 h-4 w-4" />
                  Add Product
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl">
                <DialogHeader>
                  <DialogTitle>Add New Product</DialogTitle>
                </DialogHeader>
                <div className="grid gap-4 py-4">
                  <div className="space-y-2">
                    <Label>Product Name *</Label>
                    <Input
                      placeholder="Premium Interior Paint"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    />
                  </div>
                  <div className="grid gap-4 sm:grid-cols-2">
                    <div className="space-y-2">
                      <Label>Category *</Label>
                      <Select
                        value={formData.category}
                        onValueChange={(value) => setFormData({ ...formData, category: value })}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="Interior Paint">Interior Paint</SelectItem>
                          <SelectItem value="Exterior Paint">Exterior Paint</SelectItem>
                          <SelectItem value="Tools">Tools</SelectItem>
                          <SelectItem value="Primer">Primer</SelectItem>
                          <SelectItem value="Stain">Stain</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <Label>Unit</Label>
                      <Select
                        value={formData.unit}
                        onValueChange={(value) => setFormData({ ...formData, unit: value })}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="gallon">Gallon</SelectItem>
                          <SelectItem value="quart">Quart</SelectItem>
                          <SelectItem value="set">Set</SelectItem>
                          <SelectItem value="piece">Piece</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                  <div className="grid gap-4 sm:grid-cols-2">
                    <div className="space-y-2">
                      <Label>Price ($) *</Label>
                      <Input
                        type="number"
                        placeholder="45.99"
                        value={formData.price || ""}
                        onChange={(e) => setFormData({ ...formData, price: Number(e.target.value) })}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>Stock Quantity</Label>
                      <Input
                        type="number"
                        placeholder="100"
                        value={formData.stock || ""}
                        onChange={(e) => setFormData({ ...formData, stock: Number(e.target.value) })}
                      />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <Label>Description</Label>
                    <Textarea
                      placeholder="Enter product description"
                      value={formData.description}
                      onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    />
                  </div>
                  <div className="flex gap-2">
                    <Button variant="outline" onClick={() => setIsDialogOpen(false)} className="flex-1 bg-transparent">
                      Cancel
                    </Button>
                    <Button onClick={handleSubmit} className="flex-1">
                      Create Product
                    </Button>
                  </div>
                </div>
              </DialogContent>
            </Dialog>
          </div>

          <div className="grid gap-3 sm:gap-4 grid-cols-2 lg:grid-cols-4">
            <Card className="overflow-hidden">
              <CardHeader className="pb-2 sm:pb-3">
                <CardTitle className="text-xs sm:text-sm font-medium text-muted-foreground">Total Products</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-xl sm:text-2xl font-bold">{products.length}</div>
              </CardContent>
            </Card>
            <Card className="overflow-hidden">
              <CardHeader className="pb-2 sm:pb-3">
                <CardTitle className="text-xs sm:text-sm font-medium text-muted-foreground">Total Value</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-xl sm:text-2xl font-bold">{formatUSD(totalValue)}</div>
              </CardContent>
            </Card>
            <Card className="overflow-hidden">
              <CardHeader className="pb-2 sm:pb-3">
                <CardTitle className="text-xs sm:text-sm font-medium text-muted-foreground">Low Stock Items</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-xl sm:text-2xl font-bold">{lowStockCount}</div>
              </CardContent>
            </Card>
            <Card className="overflow-hidden">
              <CardHeader className="pb-2 sm:pb-3">
                <CardTitle className="text-xs sm:text-sm font-medium text-muted-foreground">Categories</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-xl sm:text-2xl font-bold">{categories.length}</div>
              </CardContent>
            </Card>
          </div>

          <Card>
            <CardHeader>
              <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
                <div className="relative flex-1">
                  <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    placeholder="Search products..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="pl-9"
                  />
                </div>
                <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                  <SelectTrigger className="w-full sm:w-[200px]">
                    <SelectValue placeholder="All Categories" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Categories</SelectItem>
                    {categories.map((cat) => (
                      <SelectItem key={cat} value={cat}>
                        {cat}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </CardHeader>
            <CardContent>
              {filteredProducts.length === 0 ? (
                <div className="flex min-h-[250px] sm:min-h-[300px] items-center justify-center px-4">
                  <div className="text-center space-y-2">
                    <p className="text-muted-foreground">No products found.</p>
                    <p className="text-sm text-muted-foreground">Add your first product to get started!</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-3 sm:space-y-4">
                  {filteredProducts.map((product) => (
                    <Card key={product.id} className="transition-all hover:shadow-sm active:scale-[0.98]">
                      <CardContent className="p-3 sm:p-4 lg:p-6">
                        <div className="flex flex-col gap-3 sm:gap-4 sm:flex-row sm:items-start sm:justify-between">
                          <div className="flex gap-3 sm:gap-4 min-w-0">
                            <div className="flex h-12 w-12 sm:h-16 sm:w-16 shrink-0 items-center justify-center rounded-lg bg-primary/10">
                              <Package className="h-6 w-6 sm:h-8 sm:w-8 text-primary" />
                            </div>
                            <div className="min-w-0 flex-1 space-y-1">
                              <div className="flex flex-wrap items-center gap-2">
                                <h3 className="font-semibold text-sm sm:text-base truncate">{product.name}</h3>
                                <Badge
                                  variant={product.stock < 50 ? "destructive" : "default"}
                                  className="text-xs shrink-0"
                                >
                                  {product.stock < 50 ? "Low Stock" : "In Stock"}
                                </Badge>
                              </div>
                              <p className="text-xs sm:text-sm text-muted-foreground line-clamp-2">
                                {product.description}
                              </p>
                              <div className="flex flex-wrap items-center gap-2 sm:gap-3 text-xs sm:text-sm text-muted-foreground">
                                <span className="truncate">Category: {product.category}</span>
                                <span className="shrink-0">
                                  Stock: {product.stock} {product.unit}s
                                </span>
                              </div>
                            </div>
                          </div>
                          <div className="flex items-center justify-between sm:flex-col sm:items-end sm:gap-2">
                            <div className="text-left sm:text-right">
                              <p className="text-xs sm:text-sm text-muted-foreground">Price</p>
                              <p className="text-xl sm:text-2xl font-bold">{formatUSD(product.price)}</p>
                            </div>
                            <Button
                                size="icon"
                                variant="ghost"
                                className="h-8 w-8 sm:h-9 sm:w-9 shrink-0 text-destructive hover:bg-destructive/10 active:scale-95"
                                onClick={() => deleteProduct(product.id)}
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                              <Button
                                size="icon"
                                variant="ghost"
                                className="h-8 w-8 sm:h-9 sm:w-9 shrink-0 hover:bg-accent/10 active:scale-95"
                                onClick={() => {
                                  setEditingProduct(product)
                                  setEditFormData({
                                    name: product.name || "",
                                    category: product.category || "",
                                    price: product.price || 0,
                                    unit: product.unit || "",
                                    stock: product.stock || 0,
                                    description: product.description || "",
                                  })
                                  setIsEditDialogOpen(true)
                                }}
                              >
                                <Edit className="h-4 w-4" />
                              </Button>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
          <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
            <DialogContent className="max-w-2xl">
              <DialogHeader>
                <DialogTitle>Edit Product</DialogTitle>
              </DialogHeader>
              <div className="grid gap-4 py-4">
                <div className="space-y-2">
                  <Label>Product Name *</Label>
                  <Input
                    placeholder="Premium Interior Paint"
                    value={editFormData.name}
                    onChange={(e) => setEditFormData({ ...editFormData, name: e.target.value })}
                  />
                </div>
                <div className="grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label>Category *</Label>
                    <Select value={editFormData.category} onValueChange={(value) => setEditFormData({ ...editFormData, category: value })}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="Interior Paint">Interior Paint</SelectItem>
                        <SelectItem value="Exterior Paint">Exterior Paint</SelectItem>
                        <SelectItem value="Tools">Tools</SelectItem>
                        <SelectItem value="Primer">Primer</SelectItem>
                        <SelectItem value="Stain">Stain</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label>Unit</Label>
                    <Select value={editFormData.unit} onValueChange={(value) => setEditFormData({ ...editFormData, unit: value })}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="gallon">Gallon</SelectItem>
                        <SelectItem value="quart">Quart</SelectItem>
                        <SelectItem value="set">Set</SelectItem>
                        <SelectItem value="piece">Piece</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                </div>
                <div className="grid gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label>Price ($) *</Label>
                    <Input type="number" placeholder="45.99" value={editFormData.price || ""} onChange={(e) => setEditFormData({ ...editFormData, price: Number(e.target.value) })} />
                  </div>
                  <div className="space-y-2">
                    <Label>Stock Quantity</Label>
                    <Input type="number" placeholder="100" value={editFormData.stock || ""} onChange={(e) => setEditFormData({ ...editFormData, stock: Number(e.target.value) })} />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Description</Label>
                  <Textarea placeholder="Enter product description" value={editFormData.description} onChange={(e) => setEditFormData({ ...editFormData, description: e.target.value })} />
                </div>
                <div className="flex gap-2">
                  <Button variant="outline" onClick={() => setIsEditDialogOpen(false)} className="flex-1 bg-transparent">Cancel</Button>
                  <Button
                    onClick={async () => {
                      if (!editingProduct) return
                      const ok = await updateProduct(editingProduct.id, editFormData)
                      if (!ok) {
                        alert('Failed to update product on server')
                        return
                      }
                      setIsEditDialogOpen(false)
                      setEditingProduct(null)
                    }}
                    className="flex-1"
                  >
                    Save Changes
                  </Button>
                </div>
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </div>
    </MainLayout>
  )
}
